if(t.length>=3&&!isNaN(n[t.length-1])&&!isNaN(n[t.length-2])){nom=t.slice(0,t.length-2).join(' ');u=n[t.length-2];v=n[t.length-1]}else if(t.length===2&&!isNaN(n[0])&&!isNaN(n[1])){nom='P'+(++i);u=n[0];v=n[1]}else continue;
out.push(chain(nom,u,v,sys,zs))}return out}
const cols=[['Nom','nom',0],['Zone','z',0],['X 1934','X34',2],['Y 1934','Y34',2],['X 1986 (repère Nord)','X86',2],['Y 1986 (repère Nord)','Y86',2],['X Lambert zone saisie','XL',2],['Y Lambert zone saisie','YL',2],['X NTT','XN',2],['Y NTT','YN',2],['φ (gr)','pg',6],['λ (gr)','lg',6],['φ (°)','pd',7],['λ (°)','ld',7],['X UTM','XU',2],['Y UTM','YU',2],['Lat WGS84','pw',7],['Lon WGS84','lw',7],['Feuille 1/50000','fe',0],['Alerte','msg',0]];
const gm=r=>`https://www.google.com/maps?q=${r.pw.toFixed(7)},${r.lw.toFixed(7)}`,gs=r=>`https://www.google.com/maps/@${r.pw.toFixed(7)},${r.lw.toFixed(7)},120m/data=!3m1!1e3`;
function show(nt){const t=$('tab');t.innerHTML='<tr>'+cols.map(c=>`<th>${c[0]}</th>`).join('')+'<th>Google Maps</th></tr>'+R.map(r=>'<tr>'+cols.map(c=>`<td${c[1]==='msg'?' class="w"':''}>${c[2]?f(r[c[1]],c[2]):(r[c[1]]??'')}</td>`).join('')+`<td><a target="_blank" href="${gm(r)}">plan</a> · <a target="_blank" href="${gs(r)}">satellite</a></td></tr>`).join('');
$('nr').textContent=R.length+' point(s) traité(s).';const o=R.map((r,i)=>`<option value="${i}">${r.nom}</option>`).join('');$('pa').innerHTML=o;$('pb').innerHTML=o;if(R.length>1)$('pb').value=1;map();kib();lmap();if(!nt)tab(1)}
const gx=(r,s)=>s==='86'?[r.X86,r.Y86]:s==='N'?[r.XN,r.YN]:[r.XU,r.YU];
function map(){const s=$('pl').value,P=R.map(r=>gx(r,s)).filter(p=>p[0]!=null);const svg=$('svg');if(!P.length){svg.innerHTML='';return}
const xs=P.map(p=>p[0]),ys=P.map(p=>p[1]);let x0=Math.min(...xs),x1=Math.max(...xs),y0=Math.min(...ys),y1=Math.max(...ys);const w=Math.max(x1-x0,1),h=Math.max(y1-y0,1),sc=Math.min(720/w,380/h);
const tx=x=>40+(x-x0)*sc,ty=y=>420-(y-y0)*sc;let h2='';if($('poly').checked&&P.length>1)h2+=`<polyline fill="none" stroke="#2fb7a0" stroke-width="1.5" points="${P.map(p=>tx(p[0])+','+ty(p[1])).join(' ')}"/>`;
P.forEach((p,i)=>{h2+=`<circle cx="${tx(p[0])}" cy="${ty(p[1])}" r="4" fill="#7ac943"/><text x="${tx(p[0])+7}" y="${ty(p[1])-6}" font-size="11" fill="currentColor">${R[i].nom}</text>`});
h2+=`<text x="10" y="450" font-size="11" fill="#8fb3a0">Échelle ≈ ${f(100/sc,1)} m / 100 px · X→ Y↑</text>`;svg.innerHTML=h2;
$('gall').href='https://www.google.com/maps/dir/'+R.slice(0,20).map(r=>r.pw.toFixed(6)+','+r.lw.toFixed(6)).join('/');$('links').innerHTML=R.map(r=>`<a target="_blank" href="${gm(r)}">${r.nom}</a>`).join(' · ')}
const dms=g=>{const d=g*.9,x=Math.floor(Math.abs(d)),m=Math.floor((Math.abs(d)-x)*60),s=((Math.abs(d)-x)*60-m)*60;return`${x}° ${m}' ${s.toFixed(2)}"`};
function calcAB(){const A=R[$('pa').value],B=R[$('pb').value];if(!A||!B)return;const[xa,ya]=gx(A,'86'),[xb,yb]=gx(B,'86');const d=Math.hypot(xb-xa,yb-ya),g=((Math.atan2(xb-xa,yb-ya)/G)+400)%400;
const[x1,y1]=A.XN!=null&&B.XN!=null?[B.XN-A.XN,B.YN-A.YN]:[0,0];const dn=Math.hypot(x1,y1);
const p1=A.pw*Math.PI/180,p2=B.pw*Math.PI/180,dl=(B.lw-A.lw)*Math.PI/180,hv=2*6371008.8*Math.asin(Math.sqrt(Math.sin((p2-p1)/2)**2+Math.cos(p1)*Math.cos(p2)*Math.sin(dl/2)**2));
$('rc').innerHTML=`Distance plane Lambert 1986 : <b>${f(d)} m</b><br>Distance plane NTT : <b>${f(dn)} m</b><br>Distance sphérique WGS84 : <b>${f(hv)} m</b><br>Gisement A→B : <b>${f(g,4)} gr</b> = ${dms(g/.9*.9)} (${f(g*.9,4)}°)<br>ΔX = ${f(xb-xa)} m · ΔY = ${f(yb-ya)} m`}
function surf(){const s=$('sg').value,P=R.map(r=>gx(r,s)).filter(p=>p[0]!=null);if(P.length<3){$('rs').textContent='Au moins 3 points nécessaires.';return}let S=0,Pm=0;for(let i=0;i<P.length;i++){const j=(i+1)%P.length;S+=P[i][0]*P[j][1]-P[j][0]*P[i][1];Pm+=Math.hypot(P[j][0]-P[i][0],P[j][1]-P[i][1])}S=Math.abs(S)/2;
$('rs').innerHTML=`Surface : <b>${f(S)} m²</b> = ${f(S/1e4,4)} ha · Périmètre : <b>${f(Pm)} m</b> · ${P.length} sommets`}
function kib(){const mp=Math.PI/180,ph2=(21+25/60+16/3600)*mp,l2=(39+49/60+30.2/3600)*mp;$('kib').innerHTML='<tr><th>Point</th><th>Azimut vrai (gr)</th><th>Azimut vrai (°)</th><th>Convergence γ (gr)</th><th>Gisement Lambert (gr)</th><th>Distance (km)</th></tr>'+R.map(r=>{const p1=r.pw*mp,dl=l2-r.lw*mp;let az=Math.atan2(Math.sin(dl),Math.cos(p1)*Math.tan(ph2)-Math.sin(p1)*Math.cos(dl));az=(az*D+360)%360;const gam=(r.lg-L0g)*Math.sin(ZN[r.z].p*G),gl=(az/.9-gam+400)%400;
const c=Math.acos(Math.sin(p1)*Math.sin(ph2)+Math.cos(p1)*Math.cos(ph2)*Math.cos(dl))*6371.0088;return`<tr><td>${r.nom}</td><td>${f(az/.9,4)}</td><td>${f(az,4)}</td><td>${f(gam,4)}</td><td>${f(gl,4)}</td><td>${f(c,1)}</td></tr>`}).join('')}
function dl(name,txt,mime){const u=URL.createObjectURL(new Blob([txt],{type:mime}));const x=document.createElement('a');x.href=u;x.download=name;x.click();URL.revokeObjectURL(u)}
function exp(k){if(!R.length)return alert("Calculez d'abord les points.");const s=$('ex_s').value;
if(k==='csv')dl('NTT_resultats.csv','\ufeff'+cols.map(c=>c[0]).join(';')+'\n'+R.map(r=>cols.map(c=>r[c[1]]==null?'':r[c[1]]).join(';')).join('\n'),'text/csv');
if(k==='kml')dl('NTT_points.kml',`<?xml version="1.0" encoding="UTF-8"?><kml xmlns="http://www.opengis.net/kml/2.2"><Document><name>NTT</name>${R.map(r=>`<Placemark><name>${r.nom}</name><Point><coordinates>${r.lw},${r.pw},0</coordinates></Point></Placemark>`).join('')}</Document></kml>`,'application/vnd.google-earth.kml+xml');
if(k==='dxf'){let t='0\nSECTION\n2\nENTITIES\n';R.forEach(r=>{const p=gx(r,s);if(p[0]==null)return;t+=`0\nPOINT\n8\nPOINTS\n10\n${p[0].toFixed(3)}\n20\n${p[1].toFixed(3)}\n30\n0\n0\nTEXT\n8\nNOMS\n10\n${(p[0]+1).toFixed(3)}\n20\n${(p[1]+1).toFixed(3)}\n30\n0\n40\n1.5\n1\n${r.nom}\n`});dl('NTT_points.dxf',t+'0\nENDSEC\n0\nEOF\n','application/dxf')}}
let LM=null,LG=null,CK=[];
function initMap(){if(!window.L||LM)return;$('map').innerHTML='';
const g=l=>L.tileLayer('https://mt{s}.google.com/vt/lyrs='+l+'&x={x}&y={y}&z={z}',{subdomains:'0123',maxZoom:21,attribution:'© Google'});
const base={'Google Plan':g('m'),'Google Satellite':g('s'),'Google Hybride':g('y'),'Google Relief':g('p')};
LM=L.map('map',{layers:[base['Google Plan']]}).setView([34,9.5],6);L.control.layers(base).addTo(LM);L.control.scale().addTo(LM);LG=L.layerGroup().addTo(LM);
LM.on('click',ev=>{const r=chain('C'+(CK.length+1),ev.latlng.lat,ev.latlng.lng,'WGS',$('zone').value);CK.push(r);const i=CK.length-1;
L.popup().setLatLng(ev.latlng).setContent('<b>'+r.nom+'</b><br>WGS84 '+f(r.pw,6)+' , '+f(r.lw,6)+'<br>Lambert 1986 '+f(r.X86,2)+' / '+f(r.Y86,2)+'<br>NTT '+f(r.XN,2)+' / '+f(r.YN,2)+'<br>UTM '+f(r.XU,2)+' / '+f(r.YU,2)+'<br><a href="#" onclick="addClick('+i+');return false">Ajouter au tableau</a>').openOn(LM)})}
function lmap(){initMap();if(!LM)return;LG.clearLayers();const pts=R.map(r=>[r.pw,r.lw]);
R.forEach(r=>L.circleMarker([r.pw,r.lw],{radius:6,color:'#06210f',weight:2,fillColor:'#7ac943',fillOpacity:1}).bindPopup('<b>'+r.nom+'</b><br>X NTT '+f(r.XN,2)+' · Y NTT '+f(r.YN,2)).bindTooltip(r.nom,{permanent:true,direction:'right'}).addTo(LG));
if($('poly').checked&&pts.length>1)L.polyline(pts,{color:'#2fb7a0'}).addTo(LG);if(pts.length)LM.fitBounds(pts,{maxZoom:19,padding:[30,30]})}
function addClick(i){R.push(CK[i]);show(true);LM.closePopup()}
const T=['1 Saisie','2 Résultats','3 Carte & Google Maps','4 Calculs','5 Export'];
T.forEach((n,i)=>{const b=document.createElement('button');b.textContent=n;b.onclick=()=>tab(i);$('nav').appendChild(b)});
function tab(i){document.querySelectorAll('section').forEach((s,j)=>s.classList.toggle('on',i===j));[...$('nav').children].forEach((b,j)=>b.classList.toggle('on',i===j));if(i===2){initMap();if(LM)setTimeout(()=>LM.invalidateSize(),50)}}
$('go').onclick=()=>{R=parse();$('msg').textContent=R.length?'':'Aucune ligne valide.';if(R.length)show()};
$('ex').onclick=()=>{$('sys').value='L34';$('zone').value='ST';$('inp').value='8471 560574.37 306753.26\nP2 561200.00 307100.00\nP3 561350.50 306400.20\nP4 560700.00 306250.00'};
$('file').onchange=e=>{const fr=new FileReader();fr.onload=()=>{$('inp').value=fr.result};fr.readAsText(e.target.files[0])};
$('pl').onchange=$('poly').onchange=()=>{map();lmap()};$('cc').onclick=calcAB;$('cs').onclick=surf;document.querySelectorAll('[data-x]').forEach(b=>b.onclick=()=>exp(b.dataset.x));tab(0);
const th=()=>document.documentElement.dataset.theme;const lab=()=>{$('th').textContent=th()==='dark'?'☀ Mode clair':'🌙 Mode sombre'};
$('th').onclick=()=>{const n=th()==='dark'?'light':'dark';document.documentElement.dataset.theme=n;try{localStorage.setItem('ntt-theme',n)}catch(e){}lab()};lab();
$('footerDate').textContent='© '+new Date().getFullYear();
</script></body></html>
